import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { withSupabase } from "npm:@supabase/server@1";

interface ReqPayload {
  name: string;
    email: string;
      employee_number?: string;
        phone?: string;
        }

        export default {
          fetch: withSupabase({ auth: "user" }, async (req, ctx) => {
              try {
                    if (req.method !== "POST") {
                            return Response.json(
                                      { error: "Metode tidak diizinkan." },
                                                { status: 405 }
                                                        );
                                                              }

                                                                    const callerId = ctx.userClaims?.id;

                                                                          if (!callerId) {
                                                                                  return Response.json(
                                                                                            { error: "Silakan login terlebih dahulu." },
                                                                                                      { status: 401 }
                                                                                                              );
                                                                                                                    }

                                                                                                                          const admin = ctx.supabaseAdmin;

                                                                                                                                const { data: caller, error: callerError } = await admin
                                                                                                                                        .from("users")
                                                                                                                                                .select("role, is_active")
                                                                                                                                                        .eq("id", callerId)
                                                                                                                                                                .maybeSingle();

                                                                                                                                                                      if (
                                                                                                                                                                              callerError ||
                                                                                                                                                                                      !caller ||
                                                                                                                                                                                              !caller.is_active ||
                                                                                                                                                                                                      !["admin", "principal"].includes(caller.role)
                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                    return Response.json(
                                                                                                                                                                                                                              { error: "Tidak memiliki izin mendaftarkan guru." },
                                                                                                                                                                                                                                        { status: 403 }
                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                            const body: ReqPayload = await req.json();

                                                                                                                                                                                                                                                                  const name = body.name?.trim();
                                                                                                                                                                                                                                                                        const email = body.email?.trim().toLowerCase();
                                                                                                                                                                                                                                                                              const employeeNumber =
                                                                                                                                                                                                                                                                                      body.employee_number?.trim() || null;
                                                                                                                                                                                                                                                                                            const phone = body.phone?.trim() || null;

                                                                                                                                                                                                                                                                                                  if (!name || !email || !email.includes("@")) {
                                                                                                                                                                                                                                                                                                          return Response.json(
                                                                                                                                                                                                                                                                                                                    { error: "Nama dan email harus diisi dengan benar." },
                                                                                                                                                                                                                                                                                                                              { status: 400 }
                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                  const { data: existing, error: existingError } = await admin
                                                                                                                                                                                                                                                                                                                                                          .from("users")
                                                                                                                                                                                                                                                                                                                                                                  .select("id")
                                                                                                                                                                                                                                                                                                                                                                          .eq("email", email)
                                                                                                                                                                                                                                                                                                                                                                                  .maybeSingle();

                                                                                                                                                                                                                                                                                                                                                                                        if (existingError) {
                                                                                                                                                                                                                                                                                                                                                                                                return Response.json(
                                                                                                                                                                                                                                                                                                                                                                                                          { error: "Gagal memeriksa email." },
                                                                                                                                                                                                                                                                                                                                                                                                                    { status: 500 }
                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                        if (existing) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                return Response.json(
                                                                                                                                                                                                                                                                                                                                                                                                                                                          { error: "Email sudah terdaftar." },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { status: 409 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data: invited, error: inviteError } =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await admin.auth.admin.inviteUserByEmail(email, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          data: { full_name: name }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (inviteError || !invited.user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Response.json(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { error: inviteError?.message || "Gagal membuat akun." },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { status: 400 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const newUserId = invited.user.id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const { error: profileError } = await admin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .from("users")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .insert({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        id: newUserId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  full_name: name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            email: email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      role: "teacher",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                is_active: true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (profileError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await admin.auth.admin.deleteUser(newUserId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return Response.json(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { error: profileError.message },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  { status: 400 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const { error: teacherError } = await admin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .from("teachers")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .insert({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                id: newUserId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          employee_number: employeeNumber,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    phone: phone
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (teacherError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          await admin.from("users").delete().eq("id", newUserId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await admin.auth.admin.deleteUser(newUserId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return Response.json(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { error: teacherError.message },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              { status: 400 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return Response.json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  message: "Guru berhasil didaftarkan.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user_id: newUserId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.error("Pendaftaran guru gagal:", error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Response.json(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { error: "Terjadi kesalahan pada server." },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { status: 500 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };